let lang = store.get('language','en');
let currentTab = 'overview';
let adminView = 'overview';
let adminSession = null;
let currentUser = null;
const t = key => i18n[lang]?.[key] || i18n.en[key] || key;
const nameOf = g => g.name[lang] || g.name.en;
const summaryOf = g => g.summary[lang] || g.summary.en;
const main = $('#main');

function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2200)}
function icon(label,color='blue'){return `<span class="icon ${color}" aria-hidden="true">${label}</span>`}
function guideCard(g){return `<a class="guide-card ${g.color}" href="#guide/${g.slug}"><div><span class="disaster-icon ${g.color}" aria-hidden="true">${g.icon}</span><h3>${esc(nameOf(g))}</h3><p>${esc(summaryOf(g))}</p></div><span class="card-link">View safety guide</span></a>`}
function sectionHead(title,sub='',link=''){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link?`<a class="card-link" href="${link}">${t('all')}</a>`:''}</div>`}

function home(){
  return `<section class="hero"><div class="hero-inner"><span class="eyebrow">◈ Together for a safer tomorrow</span><h1>${t('prepared')}<br><span>${t('safe')}</span></h1><p>${t('intro')}</p><div class="hero-actions"><a class="btn" href="#disasters">◉ ${t('explore')}</a><a class="btn secondary" href="#emergency">☎ ${t('emergency')}</a></div></div></section>
  <div class="page"><section class="quick-grid" aria-label="${t('quick')}">
    <a class="quick-card blue" href="#disasters">${icon('△','blue')}<h3>${t('disasters')}</h3><p>Before, during and after guidance.</p></a>
    <a class="quick-card green" href="#first-aid">${icon('♥','green')}<h3>${t('firstAid')}</h3><p>Clear first response steps.</p></a>
    <a class="quick-card orange" href="#emergency">${icon('☎','orange')}<h3>${t('contacts')}</h3><p>Important numbers in one place.</p></a>
    <a class="quick-card purple" href="#kit">${icon('▣','purple')}<h3>${t('kit')}</h3><p>Prepare supplies and a family plan.</p></a>
  </section>
  <section class="section">${sectionHead(t('featured'),'Practical actions for common hazards.','#disasters')}<div class="guide-grid">${guides.slice(0,6).map(guideCard).join('')}</div></section>
  <section class="section emergency-preview"><div class="panel contact-strip">${sectionHead(t('contacts'),'Save these numbers. They can make a difference.','#emergency')}<div class="contact-mini-grid">${contacts.slice(0,4).map(c=>`<a href="tel:${c.number}" class="contact-mini ${c.color}" style="--accent:var(--${c.color})"><strong>${c.number}</strong><span>${c.name}</span></a>`).join('')}</div></div><div class="panel tips-panel">${sectionHead(t('tips'))}<ul class="tips"><li>Keep emergency numbers saved and written down.</li><li>Prepare a kit for home, school and work.</li><li>Follow official alerts; do not spread rumours.</li><li>Include children, older adults, disabilities and pets in your plan.</li></ul></div></section>
  <section class="section panel why">${sectionHead(t('why'),'Useful information, designed for stressful moments.')}<div class="feature-row"><div class="feature">${icon('⌁','green')}<strong>${t('offline')}</strong><p>Core information remains available without internet.</p></div><div class="feature">${icon('文','purple')}<strong>Multilingual</strong><p>English, తెలుగు and हिन्दी interface support.</p></div><div class="feature">${icon('✓','blue')}<strong>Clear structure</strong><p>Before, during and after actions in one pattern.</p></div><div class="feature">${icon('▯','orange')}<strong>Mobile friendly</strong><p>Large controls and responsive layouts.</p></div></div></section>
  <section class="section offline-banner"><div><h2>◫ ${t('offline')}</h2><p>${t('offlineText')}</p></div><a class="btn secondary" href="#offline">How offline mode works</a></section></div>`;
}

function disasters(){return `<div class="page"><div class="page-title"><h1>${t('disasters')}</h1><p>Learn about hazards and find the action you need quickly.</p></div><div class="toolbar"><label class="search-field">⌕ <input id="disasterSearch" type="search" placeholder="${t('search')}"></label><div class="chips"><button class="chip active" data-filter="all">All</button><button class="chip" data-filter="natural">Natural</button><button class="chip" data-filter="weather">Weather</button><button class="chip" data-filter="manmade">Human-caused</button></div></div><div id="guideGrid" class="guide-grid">${guides.map(guideCard).join('')}</div></div>`}
function guideDetail(slug){const g=guides.find(x=>x.slug===slug)||guides[0];const saved=store.get('bookmarks',[]).includes(g.slug);const panels={overview:`<h2>${t('overview')}</h2><p>${g.overview}</p><h3>${t('warning')}</h3><ul>${g.warning.map(x=>`<li>${x}</li>`).join('')}</ul>`,before:`<h2>${t('before')}</h2><ol class="step-list">${g.before.map(x=>`<li>${x}</li>`).join('')}</ol>`,during:`<h2>${t('during')}</h2><ol class="step-list">${g.during.map(x=>`<li>${x}</li>`).join('')}</ol>`,after:`<h2>${t('after')}</h2><ol class="step-list">${g.after.map(x=>`<li>${x}</li>`).join('')}</ol>`,advice:`<div class="do-dont"><section class="panel advice do"><h3>✓ ${t('dos')}</h3><ul>${g.dos.map(x=>`<li>${x}</li>`).join('')}</ul></section><section class="panel advice dont"><h3>× ${t('donts')}</h3><ul>${g.donts.map(x=>`<li>${x}</li>`).join('')}</ul></section></div>`};const translationNotice=lang==='en'?'':`<div class="callout">Detailed safety steps are shown in English until their ${lang==='te'?'Telugu':'Hindi'} translation receives safety review.</div>`;return `<div class="page"><div class="detail-hero"><div><span class="eyebrow">Disaster guide</span><h1>${esc(nameOf(g))}</h1><p>${esc(summaryOf(g))}</p></div><div class="detail-actions"><button class="btn danger" data-bookmark="${g.slug}">${saved?'★ Saved':'☆ '+t('bookmark')}</button><button class="btn secondary" onclick="print()">▣ ${t('print')}</button></div></div>${translationNotice}<div class="tabbar" role="tablist">${[['overview',t('overview')],['before',t('before')],['during',t('during')],['after',t('after')],['advice',`${t('dos')} / ${t('donts')}`]].map(([id,label])=>`<button role="tab" data-tab="${id}" class="${currentTab===id?'active':''}">${label}</button>`).join('')}</div><div class="detail-grid"><article class="panel content-panel">${panels[currentTab]||panels.overview}</article><aside class="panel side-panel"><h3>Need urgent help?</h3><p>If someone is in immediate danger, contact local emergency services.</p><a class="btn danger" href="#emergency">☎ ${t('emergency')}</a><hr><p class="meta"><strong>${t('source')}</strong><br>Preparedness summary for educational use. Content version 1.0 · Review required before public deployment.</p></aside></div></div>`}
function firstAidPage(slug){if(slug){const a=firstAid.find(x=>x.slug===slug)||firstAid[0];return `<div class="page"><div class="detail-hero"><div><span class="eyebrow">First aid quick guide</span><h1>${a.name}</h1><p>${a.summary}</p></div><a class="btn danger" href="tel:112">☎ Call 112</a></div><div class="detail-grid section"><article class="panel content-panel"><div class="callout"><strong>Check safety first.</strong> This educational guide does not replace professional medical care.</div><h2>Immediate actions</h2><ol class="step-list">${a.steps.map(x=>`<li>${x}</li>`).join('')}</ol><section class="panel advice dont"><h3>× What not to do</h3><ul>${a.avoid.map(x=>`<li>${x}</li>`).join('')}</ul></section><h3>When to seek urgent help</h3><p>${a.urgent}</p></article><aside class="panel side-panel"><h3>Emergency check</h3><p>If the person is unresponsive, not breathing normally, or in immediate danger, call 112 now and follow the operator’s instructions.</p><a href="tel:112" class="btn danger">Call 112</a><p class="meta">First-aid content must receive qualified medical review before release.</p></aside></div></div>`}return `<div class="page"><div class="page-title"><h1>${t('firstAid')}</h1><p>Simple first-response guidance. Always seek professional help when needed.</p></div><div class="guide-grid section">${firstAid.map(a=>`<a class="guide-card green" href="#first-aid/${a.slug}"><div>${icon(a.icon,'green')}<h3>${a.name}</h3><p>${a.summary}</p></div><span class="card-link">Open quick guide</span></a>`).join('')}</div></div>`}
function emergency(){return `<div class="page"><div class="detail-hero"><div><span class="eyebrow">Emergency help · India</span><h1>In an emergency?</h1><p>Stay calm. Get help. Share your location clearly.</p></div><a class="btn danger" href="tel:112">☎ Call 112</a></div><section class="section">${sectionHead(t('contacts'),'Tap to call where supported, or copy a number.')}<div class="contacts-grid">${contacts.map(c=>`<article class="card contact-card ${c.color}" style="--accent:var(--${c.color})"><span class="disaster-icon ${c.color}">☎</span><h3>${c.name}</h3><div class="number">${c.number}</div><p>${c.desc}</p><div class="contact-actions"><a class="btn small ${c.color==='red'?'danger':''}" href="tel:${c.number}">${t('call')}</a><button class="btn small secondary" data-copy="${c.number}">${t('copy')}</button></div></article>`).join('')}</div></section><section class="section emergency-preview"><div class="panel content-panel"><h2>Important calling instructions</h2><ol class="step-list"><li>Stay calm and speak clearly.</li><li>Give your exact location and a nearby landmark.</li><li>Describe the emergency and number of people affected.</li><li>Follow the operator’s instructions.</li><li>Do not hang up until told it is safe.</li></ol></div><div class="panel content-panel"><h2>Know the limitation</h2><p>This guide cannot contact responders. Calling requires a working phone and mobile or landline network.</p><div class="callout">India-focused contacts verified against 112 ERSS and the National Portal of India on 30 September 2026. Regional service availability can still vary.</div></div></section></div>`}

function kitPage(){const state=store.get('kit',{});let total=0,done=0;const groups=Object.entries(defaultKit).map(([cat,items])=>{const customs=store.get('customKit',{})[cat]||[];const all=[...items,...customs];total+=all.length;done+=all.filter(x=>state[`${cat}:${x}`]).length;return `<section class="panel check-group"><h3>${cat}</h3>${all.map((item,i)=>`<div class="check-item"><input type="checkbox" id="kit-${cat}-${i}" data-kit="${esc(cat)}:${esc(item)}" ${state[`${cat}:${item}`]?'checked':''}><label for="kit-${cat}-${i}">${esc(item)}</label>${i>=items.length?`<button class="remove-item" data-remove-kit="${esc(cat)}:${esc(item)}" aria-label="Remove ${esc(item)}">×</button>`:''}</div>`).join('')}<form class="add-row" data-add-form="${esc(cat)}"><input maxlength="60" required placeholder="Add a custom item" aria-label="New ${esc(cat)} item"><button class="btn small" type="submit">${t('add')}</button></form></section>`}).join('');const pct=total?Math.round(done/total*100):0;return `<div class="page"><div class="page-title"><h1>${t('kit')}</h1><p>Build a practical kit and keep its status on this device.</p></div><div class="kit-layout section"><aside class="panel progress-card"><div class="progress-ring" style="--progress:${pct}"><strong>${pct}%</strong></div><h2>${done} of ${total}</h2><p>items ready</p><button class="btn ghost" id="resetKit">${t('reset')}</button><p class="meta">Saved locally. Clearing browser data may remove progress.</p></aside><div>${groups}</div></div></div>`}
function planPage(){const p=store.get('plan',{});return `<div class="page"><div class="page-title"><h1>${t('plan')}</h1><p>Create a private household plan. Your entries stay on this device.</p></div><form id="planForm" class="section"><section class="panel form-section"><h2>Household and contacts</h2><div class="form-grid"><div class="field"><label for="members">Household members</label><textarea id="members" name="members" placeholder="Names and essential assistance needs">${esc(p.members||'')}</textarea></div><div class="field"><label for="contact">Out-of-area emergency contact</label><textarea id="contact" name="contact" placeholder="Name, relationship and phone">${esc(p.contact||'')}</textarea></div></div></section><section class="panel form-section"><h2>Meeting and evacuation plan</h2><div class="form-grid"><div class="field"><label for="meeting">Primary meeting point</label><input id="meeting" name="meeting" value="${esc(p.meeting||'')}" placeholder="A clear, safe location"></div><div class="field"><label for="backup">Backup meeting point</label><input id="backup" name="backup" value="${esc(p.backup||'')}" placeholder="Alternative location"></div><div class="field full"><label for="evacuation">Evacuation notes</label><textarea id="evacuation" name="evacuation" placeholder="Routes, transport and who helps whom">${esc(p.evacuation||'')}</textarea></div><div class="field full"><label for="needs">Medicines, accessibility, children, older adults and pets</label><textarea id="needs" name="needs" placeholder="Only include details useful in an emergency">${esc(p.needs||'')}</textarea></div></div></section><div class="toolbar"><button class="btn" type="submit">${t('save')}</button><button class="btn secondary" type="button" id="exportPlan">${t('export')}</button><button class="btn ghost" type="button" onclick="print()">${t('print')}</button><span id="saveState" class="save-state">${p.updatedAt?`Saved ${new Date(p.updatedAt).toLocaleString()}`:''}</span></div><div class="callout">Print a copy and keep it with your kit. A locally saved plan may be lost if the device is unavailable or browser data is cleared.</div></form></div>`}
function quiz(){const qs=[['When you feel earthquake shaking indoors, what should you do first?',['Run to the stairs','Drop, Cover and Hold On','Stand beside a window'],1,'Protect your head and neck and stay away from glass.'],['What is safest when a road is covered by moving floodwater?',['Drive slowly','Walk through with a stick','Turn around and use another route'],2,'Water can hide road damage and move a vehicle or person.'],['Where should a generator be used?',['Outdoors, away from doors and windows','Inside a garage','Near an open window'],0,'Generators produce deadly carbon monoxide.']];const progress=store.get('quiz',{index:0,score:0});const q=qs[progress.index]||qs[0];return `<div class="page"><div class="page-title"><h1>Disaster Awareness Quiz</h1><p>Practise making safer choices before an emergency.</p></div><section class="panel quiz-card"><span class="eyebrow">Question ${progress.index+1} of ${qs.length}</span><h2>${q[0]}</h2><div class="answers">${q[1].map((a,i)=>`<button class="answer" data-answer="${i}" data-correct="${q[2]}">${a}</button>`).join('')}</div><div id="quizFeedback"></div><p class="meta">Score: ${progress.score}</p></section></div>`}
function signInPage(){if(currentUser){location.hash='#profile';return '<div class="page"><p>Opening your profile…</p></div>'}return `<div class="page"><div class="page-title"><h1>Sign in</h1><p>Access your profile and preferences. Emergency guidance never requires an account.</p></div><form id="userLoginForm" class="panel auth-card"><div class="field"><label for="userEmail">Email</label><input id="userEmail" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="userPassword">Password</label><input id="userPassword" name="password" type="password" autocomplete="current-password" required></div><div class="form-actions section"><button class="btn" type="submit">Sign in</button><span id="userAuthState" class="save-state"></span></div><p class="auth-switch">New here? <a href="#sign-up">Create an account</a></p></form></div>`}

function signUpPage(){if(currentUser){location.hash='#profile';return '<div class="page"><p>Opening your profile…</p></div>'}return `<div class="page"><div class="page-title"><h1>Create account</h1><p>Create an optional profile. Safety information remains available without signing in.</p></div><form id="userRegisterForm" class="panel auth-card"><div class="form-grid"><div class="field full"><label for="registerName">Full name</label><input id="registerName" name="fullName" autocomplete="name" minlength="2" maxlength="120" required></div><div class="field"><label for="registerEmail">Email</label><input id="registerEmail" name="email" type="email" autocomplete="email" required></div><div class="field"><label for="registerPhone">Phone <span class="meta">(optional)</span></label><input id="registerPhone" name="phone" type="tel" autocomplete="tel" maxlength="24"></div><div class="field"><label for="registerPassword">Password</label><input id="registerPassword" name="password" type="password" autocomplete="new-password" minlength="8" required></div><div class="field"><label for="confirmPassword">Confirm password</label><input id="confirmPassword" name="confirmPassword" type="password" autocomplete="new-password" minlength="8" required></div><div class="field full"><label for="registerLanguage">Preferred language</label><select id="registerLanguage" name="preferredLanguage"><option value="en">English</option><option value="te">తెలుగు</option><option value="hi">हिन्दी</option></select></div></div><div class="form-actions section"><button class="btn" type="submit">Create account</button><span id="userAuthState" class="save-state"></span></div><p class="meta">Passwords are securely hashed. Household safety-plan details continue to stay on this device.</p><p class="auth-switch">Already registered? <a href="#sign-in">Sign in</a></p></form></div>`}

function profilePage(){if(!currentUser)return `<div class="page"><div class="panel auth-card"><h1>Profile</h1><p>Please sign in to view your profile.</p><a class="btn" href="#sign-in">Sign in</a></div></div>`;const initials=currentUser.fullName.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();return `<div class="page"><div class="page-title"><h1>Your profile</h1><p>Manage your account and preferred language.</p></div><section class="panel auth-card"><div class="profile-summary"><div class="profile-avatar" aria-hidden="true">${esc(initials)}</div><div><h2>${esc(currentUser.fullName)}</h2><p>${esc(currentUser.email)}</p></div></div><form id="profileForm"><div class="form-grid"><div class="field"><label for="profileName">Full name</label><input id="profileName" name="fullName" value="${esc(currentUser.fullName)}" required></div><div class="field"><label for="profilePhone">Phone</label><input id="profilePhone" name="phone" type="tel" value="${esc(currentUser.phone||'')}"></div><div class="field full"><label for="profileLanguage">Preferred language</label><select id="profileLanguage" name="preferredLanguage"><option value="en" ${currentUser.preferredLanguage==='en'?'selected':''}>English</option><option value="te" ${currentUser.preferredLanguage==='te'?'selected':''}>తెలుగు</option><option value="hi" ${currentUser.preferredLanguage==='hi'?'selected':''}>हिन्दी</option></select></div></div><div class="form-actions section"><button class="btn" type="submit">Save profile</button><button id="userLogout" class="btn ghost" type="button">Sign out</button><span id="profileState" class="save-state"></span></div></form><div class="callout"><strong>Your emergency tools remain local.</strong><p>Kit progress, bookmarks and household safety-plan details stay on this device so they remain available offline.</p></div></section></div>`}

function updateAccountLink(){const link=$('#accountLink');if(!link)return;if(currentUser){link.href='#profile';link.textContent=currentUser.fullName.split(/\s+/)[0]}else{link.href='#sign-in';link.textContent='Sign in'}}
async function loadUserSession(){try{const session=await api('/api/auth/session');currentUser=session.authenticated?session.user:null}catch{currentUser=null}updateAccountLink()}

function feedbackPage(){return `<div class="page"><div class="page-title"><h1>Report a correction</h1><p>Help the project team identify outdated, unclear or inaccessible information.</p></div><form id="feedbackForm" class="panel feedback-card"><div class="form-grid"><div class="field full"><label for="feedbackType">What needs attention?</label><select id="feedbackType" name="type" required><option value="">Choose one</option><option value="incorrect-information">Incorrect information</option><option value="outdated-contact">Outdated emergency contact</option><option value="translation">Translation problem</option><option value="accessibility">Accessibility problem</option><option value="other">Other</option></select></div><div class="field full"><label for="feedbackMessage">Details</label><textarea id="feedbackMessage" name="message" minlength="10" maxlength="2000" required placeholder="Explain what is wrong and what page you were viewing."></textarea></div></div><input type="hidden" name="pageUrl" value="${esc(location.href)}"><div class="form-actions"><button class="btn" type="submit">Submit for review</button><span id="feedbackState" class="save-state"></span></div><p class="meta">Reports are reviewed by an administrator. They never change public safety content automatically.</p></form></div>`}

function adminLogin(){return `<div class="page"><div class="page-title"><h1>Content administration</h1><p>Protected tools for reviewed safety information and emergency contacts.</p></div><form id="adminLoginForm" class="panel login-card"><h2>Administrator sign in</h2><div class="field"><label for="adminEmail">Email</label><input id="adminEmail" name="email" type="email" autocomplete="username" required></div><div class="field"><label for="adminPassword">Password</label><input id="adminPassword" name="password" type="password" autocomplete="current-password" required></div><div class="form-actions section"><button class="btn" type="submit">Sign in</button></div><div id="adminLoginState" class="admin-message meta">Configure ADMIN_EMAIL, ADMIN_PASSWORD and SESSION_SECRET in a local .env file before signing in.</div></form></div>`}

function adminPage(){
  if(!adminSession?.authenticated){setTimeout(loadAdminSession,0);return adminLogin()}
  return `<div class="page"><div class="page-title"><h1>Administration dashboard</h1><p>Manage verified content without changing the public interface.</p></div><div class="toolbar"><span class="status-tag">Signed in as ${esc(adminSession.email)}</span><button id="adminLogout" class="btn ghost small">Sign out</button></div><div class="admin-shell"><nav class="panel admin-nav" aria-label="Administration sections"><button data-admin-view="overview" class="${adminView==='overview'?'active':''}">Overview</button><button data-admin-view="contacts" class="${adminView==='contacts'?'active':''}">Emergency contacts</button><button data-admin-view="feedback" class="${adminView==='feedback'?'active':''}">Feedback review</button><button data-admin-view="workflow" class="${adminView==='workflow'?'active':''}">Content workflow</button></nav><section id="adminContent" class="panel admin-content"><p>Loading administration data…</p></section></div></div>`
}

async function api(url,options={}){const response=await fetch(url,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await response.json().catch(()=>({error:'Unexpected server response.'}));if(!response.ok)throw new Error(data.error||'Request failed.');return data}
async function loadAdminSession(){try{adminSession=await api('/api/admin/session');if(adminSession.authenticated){route();return}}catch{}adminSession={authenticated:false}}
async function loadAdminView(){const host=$('#adminContent');if(!host)return;try{if(adminView==='overview'){const d=await api('/api/admin/dashboard');host.innerHTML=`<h2>Project overview</h2><div class="stat-grid"><div class="stat-card"><strong>${d.disasters}</strong>Disaster guides</div><div class="stat-card"><strong>${d.firstAid}</strong>First-aid guides</div><div class="stat-card"><strong>${d.contacts}</strong>Active contacts</div><div class="stat-card"><strong>${d.newFeedback}</strong>New reports</div><div class="stat-card"><strong>${d.reviews}</strong>Content reviews</div></div>`}else if(adminView==='contacts'){const rows=await api('/api/admin/contacts');host.innerHTML=`<h2>Emergency contacts</h2><form id="contactCreateForm" class="panel form-section"><div class="form-grid"><div class="field"><label>Service name<input name="serviceName" required maxlength="100"></label></div><div class="field"><label>Number<input name="number" required maxlength="24"></label></div><div class="field full"><label>Description<input name="description" maxlength="180"></label></div><div class="field"><label>Region<input name="regionCode" value="IN" maxlength="8"></label></div><div class="field"><label>Official source URL<input name="sourceUrl" type="url" maxlength="500"></label></div></div><button class="btn small" type="submit">Add verified contact</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>Number</th><th>Region</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.service_name)}</td><td>${esc(r.number)}</td><td>${esc(r.region_code)}</td><td><span class="status-tag">${r.active?'Active':'Archived'}</span></td><td>${r.active?`<button class="btn small ghost" data-archive-contact="${r.id}">Archive</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;bindAdminContent()}else if(adminView==='feedback'){const rows=await api('/api/admin/feedback');host.innerHTML=`<h2>Feedback review</h2>${rows.length?`<table class="data-table"><thead><tr><th>Type</th><th>Message</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.report_type)}</td><td>${esc(r.message_text)}<br><small>${esc(r.page_url||'')}</small></td><td><span class="status-tag">${esc(r.status)}</span></td><td><button class="btn small" data-resolve-feedback="${r.id}">Resolve</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">No feedback reports yet.</p>'}`;bindAdminContent()}else{host.innerHTML=`<h2>Reviewed publishing workflow</h2><ol class="step-list"><li>Create or update content as a draft.</li><li>Complete source, medical and translation review.</li><li>Approve a version and publish it to the online API.</li><li>Devices check the content version when online.</li><li>Reviewed content is cached for offline access without replacing an open emergency guide.</li></ol><div class="callout">The MySQL schema now contains disaster, translation, first-aid, kit, quiz, review, version, feedback and audit tables.</div>`}}catch(error){host.innerHTML=`<div class="callout"><strong>Database setup required</strong><p>${esc(error.message)}</p><p>Open <code>database/schema.sql</code> in MySQL Workbench, run it, and add the database values to your local <code>.env</code> file.</p></div>`}}
function bindAdminContent(){$('#contactCreateForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/admin/contacts',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast('Emergency contact added');loadAdminView()}catch(error){toast(error.message)}});$$('[data-archive-contact]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Archive this contact?'))return;try{await api(`/api/admin/contacts/${b.dataset.archiveContact}`,{method:'DELETE'});toast('Contact archived');loadAdminView()}catch(error){toast(error.message)}}));$$('[data-resolve-feedback]').forEach(b=>b.addEventListener('click',async()=>{try{await api(`/api/admin/feedback/${b.dataset.resolveFeedback}`,{method:'PUT',body:JSON.stringify({status:'resolved'})});toast('Feedback resolved');loadAdminView()}catch(error){toast(error.message)}}))}
function offlinePage(){return `<div class="page"><div class="page-title"><h1>Offline readiness</h1><p>Essential information should remain useful even when Wi‑Fi does not.</p></div><section class="panel content-panel section"><h2>How it works</h2><ol class="step-list"><li>Open the website once while online so its files and guidance can be saved.</li><li>Use the site normally. Checklists, bookmarks, language and safety plan are stored on your device.</li><li>If connectivity is lost, the status bar changes and cached content remains available.</li><li>Reconnect periodically to receive reviewed content updates.</li></ol><div class="callout"><strong>Important:</strong> Calls still require a working phone network. Clearing browser data may remove local plans and checklist progress.</div></section></div>`}

function route(){const [base,arg]=(location.hash.slice(1)||'home').split('/');currentTab=base==='guide'?currentTab:'overview';const views={home,disasters,'first-aid':()=>firstAidPage(arg),emergency,kit:kitPage,plan:planPage,quiz,'sign-in':signInPage,'sign-up':signUpPage,profile:profilePage,feedback:feedbackPage,admin:adminPage,offline:offlinePage,guide:()=>guideDetail(arg)};main.innerHTML=(views[base]||home)();$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===base));$('#primaryNav').classList.remove('open');$('#menuBtn').setAttribute('aria-expanded','false');bind();updateAccountLink();window.scrollTo({top:0,behavior:'instant'});if(base==='admin'&&adminSession?.authenticated)setTimeout(loadAdminView,0)}
function bind(){
  $('#disasterSearch')?.addEventListener('input',filterGuides);$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');filterGuides()}));
  $$('[data-tab]').forEach(b=>b.addEventListener('click',()=>{currentTab=b.dataset.tab;route()}));
  $('[data-bookmark]')?.addEventListener('click',e=>{const saved=new Set(store.get('bookmarks',[]));saved.has(e.currentTarget.dataset.bookmark)?saved.delete(e.currentTarget.dataset.bookmark):saved.add(e.currentTarget.dataset.bookmark);store.set('bookmarks',[...saved]);toast('Saved guides updated');route()});
  $$('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast('Number copied')}catch{toast(`Number: ${b.dataset.copy}`)}}));
  $$('[data-kit]').forEach(c=>c.addEventListener('change',()=>{const state=store.get('kit',{});state[c.dataset.kit]=c.checked;store.set('kit',state);route()}));
  $$('[data-add-form]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const custom=store.get('customKit',{});const cat=f.dataset.addForm;const val=$('input',f).value.trim();if(!val)return;custom[cat]=[...(custom[cat]||[]),val];store.set('customKit',custom);route()}));
  $$('[data-remove-kit]').forEach(b=>b.addEventListener('click',()=>{const [cat,...parts]=b.dataset.removeKit.split(':');const item=parts.join(':');const custom=store.get('customKit',{});custom[cat]=(custom[cat]||[]).filter(x=>x!==item);store.set('customKit',custom);route()}));
  $('#resetKit')?.addEventListener('click',()=>{if(confirm('Reset all checklist progress and custom items?')){store.set('kit',{});store.set('customKit',{});route()}});
  $('#planForm')?.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));data.updatedAt=new Date().toISOString();if(store.set('plan',data)){ $('#saveState').textContent='Saved just now';toast('Safety plan saved on this device')}else toast('Could not save. Try printing or exporting a backup.')});
  $('#exportPlan')?.addEventListener('click',()=>{const p=store.get('plan',{});const blob=new Blob([JSON.stringify(p,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='household-safety-plan.json';a.click();URL.revokeObjectURL(a.href)});
  $('#feedbackForm')?.addEventListener('submit',async e=>{e.preventDefault();const state=$('#feedbackState');state.textContent='Submitting…';try{const result=await api('/api/feedback',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});state.textContent=`Submitted · Reference ${result.reference}`;e.currentTarget.reset()}catch(error){state.textContent=error.message}});
  $('#userLoginForm')?.addEventListener('submit',async e=>{e.preventDefault();const state=$('#userAuthState');state.textContent='Signing in…';try{const result=await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});currentUser=result.user;updateAccountLink();location.hash='#profile'}catch(error){state.textContent=error.message}});
  $('#userRegisterForm')?.addEventListener('submit',async e=>{e.preventDefault();const state=$('#userAuthState');const values=Object.fromEntries(new FormData(e.currentTarget));if(values.password!==values.confirmPassword){state.textContent='Passwords do not match.';return}delete values.confirmPassword;state.textContent='Creating account…';try{const result=await api('/api/auth/register',{method:'POST',body:JSON.stringify(values)});currentUser=result.user;lang=currentUser.preferredLanguage||lang;store.set('language',lang);updateStaticLanguage();updateAccountLink();location.hash='#profile'}catch(error){state.textContent=error.message}});
  $('#profileForm')?.addEventListener('submit',async e=>{e.preventDefault();const state=$('#profileState');state.textContent='Saving…';const values=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/profile',{method:'PUT',body:JSON.stringify(values)});currentUser={...currentUser,...values};lang=values.preferredLanguage;store.set('language',lang);updateStaticLanguage();updateAccountLink();state.textContent='Profile saved'}catch(error){state.textContent=error.message}});
  $('#userLogout')?.addEventListener('click',async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}currentUser=null;updateAccountLink();location.hash='#home'});
  $('#adminLoginForm')?.addEventListener('submit',async e=>{e.preventDefault();const state=$('#adminLoginState');state.textContent='Signing in…';try{adminSession=await api('/api/admin/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});adminSession.authenticated=true;route()}catch(error){state.textContent=error.message}});
  $('#adminLogout')?.addEventListener('click',async()=>{try{await api('/api/admin/logout',{method:'POST',body:'{}'})}catch{}adminSession={authenticated:false};route()});
  $$('[data-admin-view]').forEach(b=>b.addEventListener('click',()=>{adminView=b.dataset.adminView;$$('[data-admin-view]').forEach(x=>x.classList.toggle('active',x===b));loadAdminView()}));
  $$('[data-answer]').forEach(b=>b.addEventListener('click',()=>{const all=$$('[data-answer]');all.forEach(x=>x.disabled=true);const correct=Number(b.dataset.correct);b.classList.add(Number(b.dataset.answer)===correct?'correct':'wrong');all[correct].classList.add('correct');const state=store.get('quiz',{index:0,score:0});if(Number(b.dataset.answer)===correct)state.score++;$('#quizFeedback').innerHTML=`<div class="callout">${[['Protect your head and neck and stay away from glass.'],['Water can hide road damage and move a vehicle or person.'],['Generators produce deadly carbon monoxide.']][state.index]}</div><button class="btn" id="nextQuestion">${state.index===2?'Restart quiz':'Next question'}</button>`;$('#nextQuestion').onclick=()=>{state.index=state.index===2?0:state.index+1;if(state.index===0)state.score=0;store.set('quiz',state);route()}}));
}
function filterGuides(){const q=($('#disasterSearch')?.value||'').toLowerCase();const filter=$('[data-filter].active')?.dataset.filter||'all';$('#guideGrid').innerHTML=guides.filter(g=>(filter==='all'||g.category===filter)&&`${nameOf(g)} ${summaryOf(g)} ${g.overview}`.toLowerCase().includes(q)).map(guideCard).join('')||'<div class="empty">No locally available guide matches your search.</div>'}

function updateNetwork(){const bar=$('#statusBar');if(navigator.onLine){bar.className='status-bar';bar.textContent='Online · core guidance is saved for offline use'}else{bar.className='status-bar offline';bar.textContent='Offline · saved safety information and local tools are available'}}
function updateStaticLanguage(){document.documentElement.lang=lang;$('#languageSelect').value=lang;const labels=[['home','home'],['disasters','disasters'],['first-aid','firstAid'],['kit','kit'],['plan','plan']];labels.forEach(([nav,key])=>{const a=$(`[data-nav="${nav}"]`);if(a)a.textContent=t(key)})}
$('#menuBtn').addEventListener('click',e=>{const open=$('#primaryNav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)});$('#searchBtn').addEventListener('click',()=>{$('#searchDialog').showModal();$('#globalSearch').focus()});$('#globalSearch').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();const entries=[...guides.map(g=>({title:nameOf(g),text:`${summaryOf(g)} ${g.overview}`,url:`#guide/${g.slug}`})),...firstAid.map(a=>({title:a.name,text:`${a.summary} ${a.steps.join(' ')}`,url:`#first-aid/${a.slug}`}))];$('#searchResults').innerHTML=q?entries.filter(x=>`${x.title} ${x.text}`.toLowerCase().includes(q)).map(x=>`<a class="search-result" href="${x.url}" onclick="document.querySelector('#searchDialog').close()"><strong>${esc(x.title)}</strong><br><small>${esc(x.text.slice(0,110))}…</small></a>`).join('')||'<p class="empty">No cached result found.</p>':'<p class="empty">Search locally available disaster and first-aid guidance.</p>'});
$('#languageSelect').addEventListener('change',e=>{lang=e.target.value;store.set('language',lang);updateStaticLanguage();route()});
window.addEventListener('hashchange',route);window.addEventListener('online',updateNetwork);window.addEventListener('offline',updateNetwork);updateNetwork();updateStaticLanguage();route();loadUserSession().then(()=>{const base=(location.hash.slice(1)||'home').split('/')[0];if(['profile','sign-in','sign-up'].includes(base))route()});
if(navigator.onLine)fetch('/api/content-version').then(r=>r.json()).then(data=>{const current=store.get('contentVersion','1.0.0');if(data.version&&data.version!==current){toast(`Reviewed safety content ${data.version} is available`);store.set('contentVersion',data.version)}}).catch(()=>{});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
